DROP TABLE IF EXISTS `assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `assignments` (
  `id` varchar(191) NOT NULL,
  `teacherId` varchar(191) NOT NULL,
  `subjectId` varchar(191) NOT NULL,
  `title` varchar(191) NOT NULL,
  `description` varchar(191) NOT NULL,
  `deadline` datetime(3) NOT NULL,
  `filePath` varchar(191) DEFAULT NULL,
  `fileName` varchar(191) DEFAULT NULL,
  `maxMarks` double NOT NULL DEFAULT 100,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `assignments_teacherId_idx` (`teacherId`),
  KEY `assignments_subjectId_idx` (`subjectId`),
  KEY `assignments_deadline_idx` (`deadline`),
  CONSTRAINT `assignments_subjectId_fkey` FOREIGN KEY (`subjectId`) REFERENCES `subjects` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `assignments_teacherId_fkey` FOREIGN KEY (`teacherId`) REFERENCES `teachers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
