DROP TABLE IF EXISTS `attendance_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `attendance_sessions` (
  `id` varchar(191) NOT NULL,
  `teacherId` varchar(191) NOT NULL,
  `subjectId` varchar(191) NOT NULL,
  `departmentId` varchar(191) NOT NULL,
  `semester` int(11) NOT NULL,
  `section` varchar(191) NOT NULL DEFAULT 'A',
  `qrCode` varchar(191) NOT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT 1,
  `duration` int(11) NOT NULL DEFAULT 15,
  `startedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `endedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_sessions_qrCode_key` (`qrCode`),
  KEY `attendance_sessions_qrCode_idx` (`qrCode`),
  KEY `attendance_sessions_isActive_idx` (`isActive`),
  KEY `attendance_sessions_teacherId_idx` (`teacherId`),
  KEY `attendance_sessions_subjectId_idx` (`subjectId`),
  KEY `attendance_sessions_departmentId_fkey` (`departmentId`),
  CONSTRAINT `attendance_sessions_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `attendance_sessions_subjectId_fkey` FOREIGN KEY (`subjectId`) REFERENCES `subjects` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `attendance_sessions_teacherId_fkey` FOREIGN KEY (`teacherId`) REFERENCES `teachers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

