--
-- Table structure for table `marks`
--

DROP TABLE IF EXISTS `marks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `marks` (
  `id` varchar(191) NOT NULL,
  `studentId` varchar(191) NOT NULL,
  `subjectId` varchar(191) NOT NULL,
  `teacherId` varchar(191) NOT NULL,
  `examType` varchar(191) NOT NULL,
  `marksObtained` double NOT NULL,
  `totalMarks` double NOT NULL,
  `remarks` varchar(191) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `marks_studentId_subjectId_teacherId_examType_key` (`studentId`,`subjectId`,`teacherId`,`examType`),
  KEY `marks_studentId_idx` (`studentId`),
  KEY `marks_subjectId_idx` (`subjectId`),
  KEY `marks_examType_idx` (`examType`),
  KEY `marks_teacherId_fkey` (`teacherId`),
  CONSTRAINT `marks_studentId_fkey` FOREIGN KEY (`studentId`) REFERENCES `students` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `marks_subjectId_fkey` FOREIGN KEY (`subjectId`) REFERENCES `subjects` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `marks_teacherId_fkey` FOREIGN KEY (`teacherId`) REFERENCES `teachers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

