INSERT INTO `recommendations` VALUES ('cmqm0rrwz000meot0i19a43jr','user_s_CSE_3_A_1','attendance','Improve Overall Attendance','Your overall attendance is 50%, which is below the 75% minimum requirement. Attend upcoming classes regularly to avoid being barred from exams.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000neot0n9xmlm67','user_s_CSE_3_A_1','attendance','Attend Data Structures & Algorithms 3 Classes Regularly','Your attendance in Data Structures & Algorithms 3 is 50%. You need at least 75% to be eligible for exams in this subject.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000oeot0tj3r5bga','user_s_CSE_3_A_1','attendance','Attend Database Management Systems 3 Classes Regularly','Your attendance in Database Management Systems 3 is 50%. You need at least 75% to be eligible for exams in this subject.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000peot08mobyijh','user_s_CSE_3_A_1','attendance','Attend Operating Systems 3 Classes Regularly','Your attendance in Operating Systems 3 is 50%. You need at least 75% to be eligible for exams in this subject.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000qeot0ffl9xapy','user_s_CSE_3_A_1','attendance','Attend Computer Networks 3 Classes Regularly','Your attendance in Computer Networks 3 is 50%. You need at least 75% to be eligible for exams in this subject.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000reot0gyhnzz91','user_s_CSE_3_A_1','attendance','Attend Object Oriented Programming 3 Classes Regularly','Your attendance in Object Oriented Programming 3 is 50%. You need at least 75% to be eligible for exams in this subject.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000seot0wx76jq6r','user_s_CSE_3_A_1','career','Master Data Structures & Algorithms','DSA is fundamental for technical interviews and problem-solving. Practice on LeetCode or HackerRank.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000teot04s11noik','user_s_CSE_3_A_1','career','Strengthen Database Management Skills','DBMS knowledge is essential for backend development. Focus on SQL queries and normalization.',NULL,'high',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000ueot0lvlgfl3u','user_s_CSE_3_A_1','career','Build Operating Systems Concepts','OS concepts like process management and memory allocation are frequently tested in interviews.',NULL,'medium',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000veot0z6pbsg0t','user_s_CSE_3_A_1','career','Work on Personal Projects','Build 2-3 projects to showcase on your resume. Full-stack web or mobile apps are great starting points.',NULL,'medium',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612'),('cmqm0rrwz000weot0bpthcrdw','user_s_CSE_3_A_1','career','Practice Aptitude & Logical Reasoning','Many companies include aptitude rounds. Practice quantitative and logical reasoning regularly.',NULL,'medium',0,'2026-06-20 07:11:42.612','2026-06-20 07:11:42.612');
