--
-- Table structure for table `teachers`
--

DROP TABLE IF EXISTS `teachers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `teachers` (
  `id` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `employeeId` varchar(191) NOT NULL,
  `departmentId` varchar(191) NOT NULL,
  `specialization` varchar(191) DEFAULT NULL,
  `designation` varchar(191) NOT NULL DEFAULT 'Assistant Professor',
  `phoneNumber` varchar(191) DEFAULT NULL,
  `qualification` varchar(191) DEFAULT NULL,
  `officeRoom` varchar(191) DEFAULT NULL,
  `bio` varchar(191) DEFAULT NULL,
  `researchArea` varchar(191) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `teachers_userId_key` (`userId`),
  UNIQUE KEY `teachers_employeeId_key` (`employeeId`),
  KEY `teachers_employeeId_idx` (`employeeId`),
  KEY `teachers_departmentId_idx` (`departmentId`),
  CONSTRAINT `teachers_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `teachers_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

