--
-- Table structure for table `timetables`
--

DROP TABLE IF EXISTS `timetables`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `timetables` (
  `id` varchar(191) NOT NULL,
  `departmentId` varchar(191) NOT NULL,
  `semester` int(11) NOT NULL,
  `section` varchar(191) NOT NULL DEFAULT 'A',
  `dayOfWeek` int(11) NOT NULL,
  `periodNumber` int(11) NOT NULL,
  `subjectId` varchar(191) NOT NULL,
  `teacherId` varchar(191) NOT NULL,
  `roomNumber` varchar(191) NOT NULL,
  `startTime` varchar(191) NOT NULL,
  `endTime` varchar(191) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `timetables_departmentId_semester_section_dayOfWeek_periodNum_key` (`departmentId`,`semester`,`section`,`dayOfWeek`,`periodNumber`),
  KEY `timetables_departmentId_idx` (`departmentId`),
  KEY `timetables_teacherId_idx` (`teacherId`),
  KEY `timetables_subjectId_fkey` (`subjectId`),
  CONSTRAINT `timetables_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `timetables_subjectId_fkey` FOREIGN KEY (`subjectId`) REFERENCES `subjects` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `timetables_teacherId_fkey` FOREIGN KEY (`teacherId`) REFERENCES `teachers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

